S.append(S2(c,B+' · 1','Vì sao cần vòng lặp?',card('Lặp lại việc giống nhau',P('Muốn in dòng “Xin chào” <b>100 lần</b> thì không thể viết 100 lệnh print. Cần bảo máy: “<b>lặp lại</b> việc này 100 lần”.','Vòng lặp giúp chương trình <b>ngắn gọn</b>, xử lí được <b>lượng dữ liệu bất kì</b>, và <b>không phải sửa</b> khi dữ liệu nhiều lên.','Python có hai vòng lặp: <b>for</b> (biết trước số lần hoặc duyệt một dãy) và <b>while</b> (lặp khi điều kiện còn đúng).')),CODE('for i in range(3):\n    print("Xin chao", i)\nprint("Het")',24)+R('for i in range(3):\n    print("Xin chao", i)\nprint("Het")','',26,'Kết quả')+KEY('Khối thụt lề là <b>thân vòng lặp</b>, chạy lặp lại. Dòng <code>print("Het")</code> không thụt nên chỉ chạy <b>một lần</b> sau vòng lặp.')))
S.append(S2(c,B+' · 1','for hoạt động như thế nào?',card('Từng bước của for i in range(3)',STEPS(['Python tạo dãy giá trị <b>0, 1, 2</b>.','Lần lặp 1: gán <b>i = 0</b>, chạy thân vòng.','Lần lặp 2: gán <b>i = 1</b>, chạy thân vòng.','Lần lặp 3: gán <b>i = 2</b>, chạy thân vòng.','Hết dãy: <b>thoát</b> khỏi vòng lặp.'])),TB_:=T(tr('Lần lặp','i','Việc làm',h=True)+tr('1','0','in “Xin chao 0”')+tr('2','1','in “Xin chao 1”')+tr('3','2','in “Xin chao 2”'))+KEY('Biến <code>i</code> (biến đếm) <b>tự được gán</b> giá trị tiếp theo ở mỗi lần lặp. Số lần lặp = <b>số phần tử</b> của dãy.')))
S.append(TB(c,B+' · 1','Hàm range: ba cách viết',['Cách viết','Dãy giá trị','Số phần tử'],[['<code>range(5)</code>',RUN('print(list(range(5)))'),'5'],['<code>range(2, 7)</code>',RUN('print(list(range(2, 7)))'),'7 − 2 = 5'],['<code>range(1, 10, 3)</code>',RUN('print(list(range(1, 10, 3)))'),'3'],['<code>range(10, 0, -3)</code>',RUN('print(list(range(10, 0, -3)))'),'4'],['<code>range(5, 5)</code>',RUN('print(list(range(5, 5)))'),'0 (rỗng)'],['<code>range(5, 2)</code>',RUN('print(list(range(5, 2)))'),'0 (rỗng)']],note=KEY('<b>range(a, b)</b> lấy từ <b>a</b> đến <b>b − 1</b> (<b>không lấy b</b>). <b>range(a, b, k)</b> bước k: a, a+k, a+2k, … <b>trong khi chưa tới b</b>. Số phần tử của <code>range(a, b)</code> là <b>b − a</b> (nếu dương).')))
S.append(S2(c,B+' · 1','Bước âm: đếm ngược',card('Quy tắc',P('Bước <b>âm</b> thì dãy <b>giảm dần</b>, và phải có <b>a &gt; b</b>, nếu không dãy rỗng.','<b>range(10, 0, -3)</b>: 10, 7, 4, 1 (kế tiếp là −2, đã <b>qua</b> mốc 0 nên dừng; <b>không lấy 0</b>).','Muốn bao gồm 0: <code>range(10, -1, -3)</code>.')),CODE('print(list(range(5, 0, -1)))\nprint(list(range(5, -1, -1)))\nprint(list(range(0, 5, -1)))\nfor i in range(3, 0, -1):\n    print(i, end=" ")\nprint("Xuat phat!")',21)+R('print(list(range(5, 0, -1)))\nprint(list(range(5, -1, -1)))\nprint(list(range(0, 5, -1)))\nfor i in range(3, 0, -1):\n    print(i, end=" ")\nprint("Xuat phat!")','',22,'Kết quả')))
S.append(S2(c,B+' · 1','Biến đếm sau khi vòng lặp kết thúc',card('Điều ít người để ý',P('Sau vòng lặp, biến <code>i</code> <b>vẫn tồn tại</b> và giữ giá trị của <b>lần lặp cuối</b>.','Với <code>range(10, 0, -3)</code>: các lần lặp cho i = 10, 7, 4, 1; nên <b>sau vòng lặp i = 1</b>.','Nếu dãy rỗng thì <b>i không được tạo</b>: dùng i sẽ gây <b>NameError</b>.')),CODE('s = 0\nfor i in range(10, 0, -3):\n    s += i\nprint(s, i)\nfor k in range(0):\n    pass\nprint(k)',22)+R('s = 0\nfor i in range(10, 0, -3):\n    s += i\nprint(s, i)','',24,'Dòng in đầu tiên')+RES(OUT(ERR('for k in range(0):\n    pass\nprint(k)'),20),'Dòng cuối: dãy rỗng')+KEY('10 + 7 + 4 + 1 = <b>22</b>, i cuối = <b>1</b>: đáp án “22 1”.')))
S.append(S2(c,B+' · 1','Duyệt xâu và danh sách',card('for lấy lần lượt từng phần tử',P('<code>for ch in "Tin"</code>: ch nhận "T", "i", "n".','<code>for x in [4, 9, 2]</code>: x nhận 4, 9, 2.','Khi <b>không cần chỉ số</b>, duyệt trực tiếp phần tử gọn hơn <code>range(len(...))</code>.','Cần <b>chỉ số</b> thì dùng <code>range(len(a))</code> hoặc <code>enumerate(a)</code>.')),CODE('for ch in "Tin":\n    print(ch, end="-")\nprint()\na = [4, 9, 2]\nfor x in a:\n    print(x * 2, end=" ")\nprint()\nfor i in range(len(a)):\n    print(i, a[i])\nfor i, x in enumerate(a):\n    print(i, x)',19)+R('for ch in "Tin":\n    print(ch, end="-")\nprint()\na = [4, 9, 2]\nfor x in a:\n    print(x * 2, end=" ")\nprint()\nfor i in range(len(a)):\n    print(i, a[i])\nfor i, x in enumerate(a):\n    print(i, x)','',20,'Kết quả')))
