S.append(S2(c,B+' · 2','Mẫu 2: tích luỹ thừa số và đếm',card('Hai mẫu hay dùng',P('<b>Tích</b>: bắt đầu <b>p = 1</b> (không phải 0!), mỗi lần <code>p *= i</code>. Ví dụ n! = 1×2×…×n.','<b>Đếm</b>: bắt đầu <b>dem = 0</b>, mỗi lần <b>thoả điều kiện</b> thì <code>dem += 1</code>.')),CODE('p = 1\nfor i in range(1, 6):\n    p *= i\nprint(p)\ndem = 0\nfor i in range(1, 21):\n    if i % 3 == 0:\n        dem += 1\nprint(dem)',21)+R('p = 1\nfor i in range(1, 6):\n    p *= i\nprint(p)\ndem = 0\nfor i in range(1, 21):\n    if i % 3 == 0:\n        dem += 1\nprint(dem)','',24,'Kết quả')+KEY('5! = 120. Có <b>6</b> bội của 3 trong 1…20 (3, 6, 9, 12, 15, 18) = 20 // 3.')))
S.append(S2(c,B+' · 2','Mẫu 3: tìm giá trị lớn nhất và vị trí',card('Phương pháp “người giữ kỉ lục”',STEPS(['Gọi phần tử đầu là <b>lớn nhất tạm thời</b>.','Duyệt các phần tử còn lại.','Gặp phần tử <b>lớn hơn</b> kỉ lục thì <b>cập nhật</b>.'])),CODE('a = [4, 9, 2, 9, 7]\nlon = a[0]\nvt = 0\nfor i in range(1, len(a)):\n    if a[i] > lon:\n        lon = a[i]\n        vt = i\nprint(lon, vt)',21)+R('a = [4, 9, 2, 9, 7]\nlon = a[0]\nvt = 0\nfor i in range(1, len(a)):\n    if a[i] > lon:\n        lon = a[i]\n        vt = i\nprint(lon, vt)','',24,'Kết quả')+KEY('Dùng <b>&gt;</b> (không phải &gt;=) nên giữ vị trí <b>xuất hiện đầu tiên</b> của 9 → vị trí 1.')))
S.append(TB(c,B+' · 2','Theo dõi tìm lớn nhất: a = [4, 9, 2, 9, 7]',['i','a[i]','a[i] &gt; lon ?','lon','vt'],[['(đầu)','—','—','4','0'],['1','9','9 &gt; 4: đúng','9','1'],['2','2','2 &gt; 9: sai','9','1'],['3','9','9 &gt; 9: sai','9','1'],['4','7','7 &gt; 9: sai','9','1']],note=KEY('Muốn lấy vị trí <b>cuối cùng</b> của giá trị lớn nhất thì dùng <b>&gt;=</b>. Hai kí hiệu cho <b>hai kết quả khác nhau</b> khi có giá trị trùng.')))
S.append(S2(c,B+' · 2','Mẫu 4: duyệt xâu và phân loại kí tự',card('Phương thức kiểm tra kí tự',ul(['<code>ch.isdigit()</code>: là chữ số.','<code>ch.isupper()</code>, <code>ch.islower()</code>: chữ hoa, chữ thường.','<code>ch.isalpha()</code>: là chữ cái.','<code>ch.isspace()</code>: là khoảng trắng.'],6)),CODE('s = "Tin Hoc 12 - NB 2026"\ndem = tong = 0\nfor ch in s:\n    if ch.isdigit():\n        tong += int(ch)\n    elif ch.isupper():\n        dem += 1\nprint(dem, tong)',20)+R('s = "Tin Hoc 12 - NB 2026"\ndem = tong = 0\nfor ch in s:\n    if ch.isdigit():\n        tong += int(ch)\n    elif ch.isupper():\n        dem += 1\nprint(dem, tong)','',24,'Kết quả')+KEY('Chữ hoa: T, H, N, B → <b>4</b>. Chữ số: 1+2+2+0+2+6 = <b>13</b>.')))
S.append(S2(c,B+' · 2','Mẫu 5: xây dựng xâu, danh sách trong vòng lặp',card('Tích luỹ không chỉ là số',P('Có thể <b>tích luỹ xâu</b> (<code>s += "a"</code>) hoặc <b>danh sách</b> (<code>kq.append(x)</code>).','Bắt đầu từ <b>xâu rỗng ""</b> hoặc <b>danh sách rỗng []</b>.')),CODE('s = ""\nfor i in range(1, 8):\n    if i % 2:\n        continue\n    s += str(i)\nprint(s)\nkq = []\nfor i in range(1, 11):\n    if i % 3 == 0:\n        kq.append(i * i)\nprint(kq)',20)+R('s = ""\nfor i in range(1, 8):\n    if i % 2:\n        continue\n    s += str(i)\nprint(s)\nkq = []\nfor i in range(1, 11):\n    if i % 3 == 0:\n        kq.append(i * i)\nprint(kq)','',24,'Kết quả')+KEY('<b>continue</b> bỏ qua phần còn lại của vòng lặp hiện tại (bỏ qua số lẻ) → chỉ nối 2, 4, 6 thành “246”.')))
# 3 lồng
S.append(S2(c,B+' · 3','Vòng lặp lồng nhau',card('Đồng hồ: kim giờ và kim phút',P('Vòng lặp <b>trong</b> chạy <b>trọn vẹn</b> mỗi lần vòng lặp <b>ngoài</b> lặp một lần.','Tổng số lần chạy thân vòng trong = (số lần vòng ngoài) × (số lần vòng trong).','Khi vòng trong <b>phụ thuộc</b> vòng ngoài (ví dụ <code>range(i)</code>), số lần mỗi vòng <b>khác nhau</b>: phải cộng từng vòng.')),CODE('for i in range(1, 4):\n    for j in range(1, 3):\n        print(i, j)',24)+R('for i in range(1, 4):\n    for j in range(1, 3):\n        print(i, j)','',24,'Kết quả: 3 × 2 = 6 dòng')))
S.append(TB(c,B+' · 3','Đếm số lần lặp: for i in 1..5, for j in range(i)',['i','vòng trong chạy','số lần','tổng tích luỹ'],[['1','j = 0','1','1'],['2','j = 0, 1','2','3'],['3','j = 0, 1, 2','3','6'],['4','j = 0..3','4','10'],['5','j = 0..4','5','15']],note=KEY('Tổng = 1 + 2 + 3 + 4 + 5 = <b>15</b>. Công thức tổng quát: <b>n(n+1)/2</b>. Đây là “tam giác”: số lần lặp tăng dần, <b>không phải</b> 5 × 5.')))
S.append(TB(c,B+' · 3','Bảng theo dõi có điều kiện: (i + j) % 2 == 0',['i','j','i + j','(i+j) % 2 == 0 ?','x'],[['1','0','1','sai','0'],['2','0','2','<b>đúng</b>','1'],['2','1','3','sai','1'],['3','0','3','sai','1'],['3','1','4','<b>đúng</b>','2'],['3','2','5','sai','2'],['4','0 … 3','4,5,6,7','j=0 và j=2 đúng','4'],['5','0 … 4','5…9','j=1 và j=3 đúng','6']],note=KEY('Tính tay ra <b>x = 6</b>. Kiểm tra bằng máy: ')+OUT(RUN('x = 0\nfor i in range(1, 6):\n    for j in range(i):\n        if (i + j) % 2 == 0:\n            x += 1\nprint(x)'),22)))
S.append(S2(c,B+' · 3','In hình bằng vòng lặp lồng nhau',card('Ba hình cơ bản',P('<code>print("*" * i)</code> in i dấu sao: dùng <b>một vòng</b> cho mỗi dòng.','Tam giác cân cần <b>dấu cách đệm</b> bên trái: <code>" " * (n - i)</code>.')),CODE('n = 3\nfor i in range(1, n + 1):\n    print("*" * i)\nfor i in range(1, n + 1):\n    print(" " * (n - i) + "*" * (2 * i - 1))\nfor i in range(1, 4):\n    for j in range(1, 4):\n        print(i * j, end=" ")\n    print()',19)+R('n = 3\nfor i in range(1, n + 1):\n    print("*" * i)\nfor i in range(1, n + 1):\n    print(" " * (n - i) + "*" * (2 * i - 1))\nfor i in range(1, 4):\n    for j in range(1, 4):\n        print(i * j, end=" ")\n    print()','',19,'Kết quả')))
S.append(S2(c,B+' · 3','Cặp (i, j) với i &lt; j: độ phức tạp tăng',card('Đếm cặp thoả điều kiện',P('Để xét <b>mọi cặp</b> (i, j) với i &lt; j: cho j chạy <b>từ i + 1</b> để mỗi cặp chỉ xét <b>một lần</b>.','Với n phần tử có <b>n(n − 1)/2</b> cặp. Nếu n = 10⁵ thì quá nhiều: cần cách làm thông minh hơn (học ở bài độ phức tạp).')),CODE('t = 0\nfor i in range(1, 20):\n    for j in range(i + 1, 20):\n        if (i + j) % 5 == 0:\n            t += 1\nprint(t)\nprint(19 * 18 // 2)',21)+R('t = 0\nfor i in range(1, 20):\n    for j in range(i + 1, 20):\n        if (i + j) % 5 == 0:\n            t += 1\nprint(t)\nprint(19 * 18 // 2)','',24,'Kết quả: 35 cặp trong tổng 171 cặp')))
# 4 break continue else
S.append(S2(c,B+' · 4','break và continue',card('Hai lệnh điều khiển vòng lặp',ul(['<b>break</b>: <b>thoát hẳn</b> khỏi vòng lặp gần nhất.','<b>continue</b>: <b>bỏ qua</b> phần còn lại của lần lặp này, sang lần lặp kế tiếp.'],8)+P('<b>break</b> hay dùng khi <b>đã tìm thấy</b> điều cần tìm.')),CODE('for i in range(1, 10):\n    if i == 4:\n        break\n    print(i, end=" ")\nprint("|", i)\nfor i in range(1, 8):\n    if i % 3 == 0:\n        continue\n    print(i, end=" ")',21)+R('for i in range(1, 10):\n    if i == 4:\n        break\n    print(i, end=" ")\nprint("|", i)\nfor i in range(1, 8):\n    if i % 3 == 0:\n        continue\n    print(i, end=" ")','',24,'Kết quả')+KEY('Sau <b>break</b>, i giữ giá trị lúc thoát (4).')))
S.append(S2(c,B+' · 4','for … else: else chạy khi KHÔNG bị break',card('Quy tắc dễ nhầm',P('Khối <b>else</b> của <b>for</b> chạy khi vòng lặp <b>kết thúc bình thường</b> (hết dãy), nghĩa là <b>không gặp break</b>.','Nếu vòng lặp bị <b>break</b> thì <b>else bị bỏ qua</b>.','Ứng dụng kinh điển: <b>kiểm tra số nguyên tố</b>.')),CODE('n = 29\nfor i in range(2, n):\n    if n % i == 0:\n        print("hop so")\n        break\nelse:\n    print("nguyen to")\nprint("ket thuc")',22)+R('n = 29\nfor i in range(2, n):\n    if n % i == 0:\n        print("hop so")\n        break\nelse:\n    print("nguyen to")\nprint("ket thuc")','',24,'Kết quả (n = 29)')+KEY('29 không chia hết cho số nào từ 2 đến 28 nên <b>không break</b> → else chạy. Với n = 9: gặp i = 3, in “hop so”, <b>break</b>, bỏ qua else.')))
S.append(S2(c,B+' · 4','break trong vòng lặp lồng nhau chỉ thoát một tầng',card('Chú ý',P('<b>break</b> chỉ thoát <b>vòng lặp trong cùng</b> chứa nó, không thoát vòng ngoài.','Muốn thoát cả hai tầng: dùng <b>cờ (flag)</b> hoặc đặt trong <b>hàm</b> rồi <code>return</code>.')),CODE('for i in range(1, 4):\n    for j in range(1, 4):\n        if j == 2:\n            break\n        print(i, j)',22)+R('for i in range(1, 4):\n    for j in range(1, 4):\n        if j == 2:\n            break\n        print(i, j)','',24,'Kết quả')+KEY('Mỗi lần j = 2 thì vòng trong thoát, nhưng <b>vòng ngoài vẫn chạy tiếp</b> i = 2, 3.')))
S.append(SELF(c,B+' · 4','Tự kiểm tra: số lần lặp và giá trị cuối','Cho đoạn chương trình. (a) Số lần print chạy? (b) Giá trị cuối cùng của i, s?','s = 0\nfor i in range(2, 20, 4):\n    if i % 3 == 0:\n        continue\n    s += i\n    print(i)\nprint(s, i)',P('<b>Dãy i</b>: 2, 6, 10, 14, 18 (bước 4, dừng trước 20).','<b>Bỏ qua</b> (continue) khi i chia hết cho 3: i = 6 và 18.','Các lần print: i = 2, 10, 14 → <b>3 lần</b>; s = 2 + 10 + 14 = <b>26</b>; i cuối = <b>18</b> (vòng lặp vẫn chạy tới 18).')+R('s = 0\nfor i in range(2, 20, 4):\n    if i % 3 == 0:\n        continue\n    s += i\n    print(i)\nprint(s, i)','',22,'Kết quả thật'),20))
S.append(SELF(c,B+' · 4','Tự kiểm tra (HSG): đếm số cặp','Cho n = 12. Đếm số cặp (i, j) với 1 ≤ i &lt; j ≤ n và (i + j) chia hết cho 4. Hãy nêu cách tính và kết quả.','n = 12\nt = 0\nfor i in range(1, n + 1):\n    for j in range(i + 1, n + 1):\n        if (i + j) % 4 == 0:\n            t += 1\nprint(t)',P('Số dư của i khi chia 4: <b>0</b> gồm 4, 8, 12 (3 số); <b>1</b>: 1, 5, 9 (3); <b>2</b>: 2, 6, 10 (3); <b>3</b>: 3, 7, 11 (3).','Tổng chia hết cho 4 khi (dư 0, dư 0), (dư 2, dư 2), (dư 1, dư 3).','Cặp (0,0): C(3,2) = 3; cặp (2,2): C(3,2) = 3; cặp (1,3): 3×3 = 9. Tổng = <b>15</b>.')+R('n = 12\nt = 0\nfor i in range(1, n + 1):\n    for j in range(i + 1, n + 1):\n        if (i + j) % 4 == 0:\n            t += 1\nprint(t)','',24,'Kết quả thật')+KEY('Chia theo <b>số dư</b> giúp đếm không cần duyệt cặp: kĩ thuật quan trọng khi n rất lớn.'),20))
S+=END(c,B,['<b>for</b> gán lần lượt từng phần tử của dãy cho biến đếm rồi chạy thân vòng.','<b>range(a, b, k)</b>: từ a, bước k, <b>không lấy b</b>; bước âm đếm ngược; có thể rỗng.','Sau vòng lặp, biến đếm giữ <b>giá trị lần lặp cuối</b>.','Mẫu: <b>tổng (0)</b>, <b>tích (1)</b>, <b>đếm (0)</b>, <b>lớn nhất</b> (cập nhật).','Lồng nhau: số lần = tổng số lần vòng trong qua từng vòng ngoài.','<b>break</b> thoát; <b>continue</b> bỏ lần này; <b>else</b> của for chạy khi <b>không break</b>.'],[('range(10, 0, -3)','10, 7, 4, 1'),('Biến tích luỹ tích','khởi tạo 1'),('else của for','khi không break'),('i cuối vòng','giữ giá trị cuối')],'Đặt <b>khởi tạo</b> trong thân vòng; nhầm số phần tử của range.',['<b>range(a, b)</b> có <b>b − a</b> phần tử.','<b>for … else</b>: else chạy khi hết dãy.','<b>break</b> chỉ thoát vòng trong cùng.','Đếm cặp bằng <b>số dư</b> thay cho duyệt cặp.'],['<b>Tổng của dãy</b>: công thức n(n+1)/2.','<b>Độ phức tạp</b> O(n²) của vòng lặp lồng.','<b>Hàm sinh</b> (generator) thay cho danh sách lớn.'],
 [('<code>len(range(3, 20, 4))</code>?',),('<code>sum(range(5))</code>?',),('Sau <code>for i in range(4): pass</code>, i bằng?',),('Vòng lặp lồng <code>for i in range(4): for j in range(3)</code> chạy mấy lần thân?',),('<code>for … else</code>: khi nào else chạy?',)],
 [('Dãy 3, 7, 11, 15, 19: <b>5</b>.',),('0+1+2+3+4 = <b>10</b>.',),('<b>3</b> (lần lặp cuối).',),('4 × 3 = <b>12</b>.',),('Khi vòng lặp hết dãy mà <b>không gặp break</b>.',)],
 [('Mức 1. In tổng các số chẵn từ 1 đến n. Thử n = 10.',),('Mức 1. In bảng cửu chương của số k (k × 1 đến k × 10). Thử k = 7.',),('Mức 2. Đếm số chữ cái hoa, chữ số trong xâu nhập vào. Thử “Tin Hoc 12 - NB 2026”.',),('Mức 2. Tìm số lớn nhì (khác lớn nhất) trong dãy. Thử 4 9 2 9 7.',),('Mức 3 (HSG). Đếm cặp (i, j), 1 ≤ i &lt; j ≤ 30 mà i·j chia hết cho 6 (không dùng công thức).',),('Mức 3 (HSG). Đếm số cặp (i, j) 1 ≤ i, j ≤ 100 với i² + j² là số chính phương. Gợi ý: dùng <code>math.isqrt</code>.',)],
 [(RUN('n=10\nprint(sum(i for i in range(2,n+1,2)))')+' (2+4+6+8+10).',),('<code>for i in range(1, 11): print(7, "x", i, "=", 7 * i)</code>',),('<code>sum(c.isupper() for c in s)</code> và <code>sum(c.isdigit() for c in s)</code> → '+RUN('s="Tin Hoc 12 - NB 2026"\nprint(sum(c.isupper() for c in s), sum(c.isdigit() for c in s))')+'.',),('<code>sorted(set(a))[-2]</code> → '+RUN('a=[4,9,2,9,7]\nprint(sorted(set(a))[-2])')+' (loại trùng rồi lấy phần tử áp cuối).',),('Duyệt hai vòng, điều kiện <code>i * j % 6 == 0</code> → '+RUN('t=0\nfor i in range(1,31):\n    for j in range(i+1,31):\n        if i*j%6==0: t+=1\nprint(t)')+' cặp.',),('<code>from math import isqrt</code>; với mỗi (i, j): <code>s = i*i + j*j; isqrt(s)**2 == s</code> → '+RUN('from math import isqrt\nt=0\nfor i in range(1,101):\n    for j in range(1,101):\n        s=i*i+j*j\n        if isqrt(s)**2==s: t+=1\nprint(t)')+' cặp (có thứ tự).',)],hper=2)
mkdeck('p2b.html','Python 2B · Vòng lặp for và hàm range',S)
